window.GL_EXTENDED_MATH_SCIENTIST_FILES = Object.assign(
  window.GL_EXTENDED_MATH_SCIENTIST_FILES || {}, {
  'astra/ConjectureAgent.astra': '// Pipeline: request > !generated > GL candidate > inform(scientist)\nagent ConjectureAgent extends ResearchOntology {\n    module gl.astra.GL gl;\n    module Console console;\n    module Cartago cartago;\n\n    types conjecture_state {\n        formula binding(string);\n        formula generated_for(string);\n    }\n\n    initial !start();\n\n    rule +!start() {\n        cartago.link();\n        +binding(gl.bind("conjecture-agent", "groq", "openai/gpt-oss-120b", ""));\n        send(inform, "main", agent_ready("conjecture"));\n        console.println("[Conjecture] Ready.");\n    }\n\n    rule @message(request, string sender,\n                  conjecture_request(string taskId, string problem, string context)) {\n        !generated(taskId, problem, context, sender);\n    }\n\n    // GL generates candidate mathematical content but does not adopt it.\n    rule +!generated(string taskId, string problem, string context, string sender) :\n        binding(string bid) {\n        !deliberated(taskId,\n            gl.call(bid, taskId + "-conjecture", "llm.answer", "ANSWER",\n                "Act as a mathematical conjecture generator. " +\n                "Problem: " + problem + ". Context: " + context + ". " +\n                "Propose ONE precise mathematical statement. " +\n                "Return leanProposition as a SINGLE-LINE Lean 4 proposition only, " +\n                "without theorem, lemma, :=, by, proof, import, namespace or end. " +\n                "Return testPredicate as a Symja boolean expression over one integer variable " +\n                "for finite falsification. Return min and max as integer strings. " +\n                "Return symbolicCheck as a Symja boolean expression that captures a useful " +\n                "symbolic consequence/identity if one exists, otherwise symbolicCheck=NONE.",\n                "statement,leanProposition,testPredicate,variable,min,max,symbolicCheck", ""),\n            sender);\n    }\n\n    rule +!deliberated(string taskId, string rid, string sender) :\n        gl.decide(gl.candidate(rid)) == "ADMISSIBLE" {\n        string cid = gl.candidate(rid);\n        send(inform, sender,\n            conjecture_proposed(taskId, cid,\n                gl.get(cid, "statement"),\n                gl.get(cid, "leanProposition"),\n                gl.get(cid, "testPredicate"),\n                gl.get(cid, "variable"),\n                gl.get(cid, "min"),\n                gl.get(cid, "max"),\n                gl.get(cid, "symbolicCheck")));\n        +generated_for(taskId);\n        console.println("[Conjecture] Candidate proposed: " + cid);\n    }\n\n    rule +!deliberated(string taskId, string rid, string sender) {\n        send(inform, sender,\n            conjecture_failed(taskId,\n                "GL conjecture candidate was not admissible: " + gl.result(rid)));\n    }\n\n    rule -!generated(string taskId, string problem, string context, string sender) :\n        ~generated_for(taskId) {\n        send(inform, sender,\n            conjecture_failed(taskId, "conjecture generation execution failed"));\n    }\n}\n',
  'astra/CounterexampleAgent.astra': '// Pipeline: request > !searched > CounterexampleArtifact > inform(scientist)\nagent CounterexampleAgent extends ResearchOntology {\n    module Cartago cartago;\n    module Console console;\n\n    types counterexample_state {\n        formula instrument(cartago.ArtifactId);\n        formula search_complete(string, string);\n    }\n\n    initial !start();\n\n    rule +!start() {\n        cartago.link();\n        cartago.lookupArtifact("counterexample", cartago.ArtifactId id);\n        +instrument(id);\n        send(inform, "main", agent_ready("counterexample"));\n        console.println("[Counterexample] Ready.");\n    }\n\n    rule @message(request, string sender,\n                  counterexample_request(string taskId, string cid,\n                                         string predicate, string variable,\n                                         string min, string max)) {\n        !searched(taskId, cid, predicate, variable, min, max, sender);\n    }\n\n    rule +!searched(string taskId, string cid, string predicate,\n                    string variable, string min, string max, string sender) :\n        instrument(cartago.ArtifactId id) {\n        cartago.operation(id,\n            searchIntegers(predicate, variable, min, max,\n                           string status, string witness));\n        +search_complete(cid, status);\n        send(inform, sender,\n            counterexample_response(taskId, cid, status, witness));\n        console.println("[Counterexample] " + cid + " -> " + status +\n                        " witness=" + witness);\n    }\n\n    rule -!searched(string taskId, string cid, string predicate,\n                    string variable, string min, string max, string sender) :\n        ~search_complete(cid, string _) {\n        send(inform, sender,\n            counterexample_response(taskId, cid, "SEARCH_FAILED", ""));\n    }\n}\n',
  'astra/FormalizationAgent.astra': '// Pipeline: request > GL semantic review > GL assessment > inform(scientist)\nagent FormalizationAgent extends ResearchOntology {\n    module gl.astra.GL gl;\n    module Console console;\n    module Cartago cartago;\n\n    types formalization_state {\n        formula binding(string);\n        formula review_complete(string);\n    }\n\n    initial !start();\n\n    rule +!start() {\n        cartago.link();\n        +binding(gl.bind("formalization-agent", "groq", "openai/gpt-oss-120b", ""));\n        send(inform, "main", agent_ready("formalization"));\n        console.println("[Formalization] Ready.");\n    }\n\n    rule @message(request, string sender,\n                  formalization_review_request(string taskId, string cid,\n                                               string statement,\n                                               string leanProposition)) {\n        !reviewed(taskId, cid, statement, leanProposition, sender);\n    }\n\n    rule +!reviewed(string taskId, string cid, string statement,\n                    string leanProposition, string sender) :\n        binding(string bid) {\n        !deliberated(taskId, cid,\n            gl.call(bid, taskId + "-formalization", "llm.answer", "ANSWER",\n                "Independently compare the natural-language mathematical statement with " +\n                "the Lean 4 proposition. Decide whether the Lean proposition formalises " +\n                "the same claim, with the same domain, quantifiers, assumptions and conclusion. " +\n                "Do not review the proof. Return verdict exactly APPROVE or REJECT and reason. " +\n                "Natural statement: " + statement +\n                ". Lean proposition: " + leanProposition,\n                "verdict,reason", ""),\n            sender);\n    }\n\n    rule +!deliberated(string taskId, string cid, string rid, string sender) :\n        gl.decide(gl.candidate(rid)) == "ADMISSIBLE" &\n        gl.get(gl.candidate(rid), "verdict") == "APPROVE" {\n        string rcid = gl.candidate(rid);\n        string reason = gl.get(rcid, "reason");\n        gl.accept(rcid, "formalization review retained");\n        string assessmentId =\n            gl.judge(cid, "formalization-agent", "APPROVE", 0.90, reason);\n        +review_complete(cid);\n        send(inform, sender,\n            formalization_review_response(taskId, cid, "APPROVE", reason, 0.90));\n    }\n\n    rule +!deliberated(string taskId, string cid, string rid, string sender) :\n        gl.decide(gl.candidate(rid)) == "ADMISSIBLE" &\n        gl.get(gl.candidate(rid), "verdict") == "REJECT" {\n        string rcid = gl.candidate(rid);\n        string reason = gl.get(rcid, "reason");\n        gl.accept(rcid, "formalization review retained");\n        string assessmentId =\n            gl.judge(cid, "formalization-agent", "REJECT_VERDICT", 0.90, reason);\n        +review_complete(cid);\n        send(inform, sender,\n            formalization_review_response(taskId, cid, "REJECT", reason, 0.90));\n    }\n\n    rule +!deliberated(string taskId, string cid, string rid, string sender) {\n        send(inform, sender,\n            formalization_review_response(taskId, cid, "REVIEW_FAILED",\n                "No admissible formalization review was produced.", 1.0));\n    }\n\n    rule -!reviewed(string taskId, string cid, string statement,\n                    string leanProposition, string sender) :\n        ~review_complete(cid) {\n        send(inform, sender,\n            formalization_review_response(taskId, cid, "REVIEW_FAILED",\n                "formalization review execution failed", 1.0));\n    }\n}\n',
  'astra/FormalVerifierAgent.astra': '// Pipeline: request > !verified > FormalProverArtifact > inform(scientist)\nagent FormalVerifierAgent extends ResearchOntology {\n    module Cartago cartago;\n    module Console console;\n\n    types verifier_state {\n        formula prover(cartago.ArtifactId);\n        formula verification_complete(string, string);\n    }\n\n    initial !start();\n\n    rule +!start() {\n        cartago.link();\n        cartago.lookupArtifact("formal-prover", cartago.ArtifactId id);\n        +prover(id);\n        send(inform, "main", agent_ready("formal-verifier"));\n        console.println("[FormalVerifier] Ready.");\n    }\n\n    rule @message(request, string sender,\n                  formal_verification_request(string taskId, string proofCid,\n                                              string leanProposition,\n                                              string leanProof)) {\n        !verified(taskId, proofCid, leanProposition, leanProof, sender);\n    }\n\n    // The artifact owns the theorem wrapper. The generated proof cannot replace\n    // the proposition that was independently reviewed earlier.\n    rule +!verified(string taskId, string proofCid,\n                    string leanProposition, string leanProof, string sender) :\n        prover(cartago.ArtifactId id) {\n        cartago.operation(id,\n            verifyLean(leanProposition, leanProof,\n                       string status, string details));\n        +verification_complete(proofCid, status);\n        send(inform, sender,\n            formal_verification_response(taskId, proofCid, status, details));\n        console.println("[FormalVerifier] " + proofCid + " -> " + status);\n    }\n\n    rule -!verified(string taskId, string proofCid,\n                    string leanProposition, string leanProof, string sender) :\n        ~verification_complete(proofCid, string _) {\n        send(inform, sender,\n            formal_verification_response(taskId, proofCid,\n                                         "VERIFICATION_FAILED",\n                                         "formal prover operation failed"));\n    }\n}\n',
  'astra/KnowledgeAgent.astra': '// Pipeline: local-corpus request > !checked > KnowledgeArtifact > inform(scientist)\nagent KnowledgeAgent extends ResearchOntology {\n    module Cartago cartago;\n    module Console console;\n\n    types knowledge_state {\n        formula knowledge_store(cartago.ArtifactId);\n        formula checked(string);\n    }\n\n    initial !start();\n\n    rule +!start() {\n        cartago.link();\n        cartago.lookupArtifact("knowledge", cartago.ArtifactId id);\n        +knowledge_store(id);\n        send(inform, "main", agent_ready("knowledge"));\n        console.println("[Knowledge] Ready.");\n    }\n\n    rule @message(request, string sender,\n                  novelty_request(string taskId, string proofCid,\n                                  string statement)) {\n        !checked(taskId, proofCid, statement, sender);\n    }\n\n    // This is deliberately only a LOCAL corpus check. It never declares novelty.\n    rule +!checked(string taskId, string proofCid,\n                   string statement, string sender) :\n        knowledge_store(cartago.ArtifactId id) {\n        cartago.operation(id,\n            lookupStatement(statement, string status, string evidence));\n        +checked(proofCid);\n        send(inform, sender,\n            novelty_response(taskId, proofCid, status, evidence));\n        console.println("[Knowledge] " + proofCid + " -> " + status);\n    }\n\n    rule -!checked(string taskId, string proofCid,\n                   string statement, string sender) :\n        ~checked(proofCid) {\n        send(inform, sender,\n            novelty_response(taskId, proofCid,\n                "LOCAL_CORPUS_CHECK_FAILED", "knowledge lookup failed"));\n    }\n}\n',
  'astra/Main.astra': '// Pipeline: main > !environment_ready > !artifacts_ready > !agents_created\n/**\n * Mathematician-Scientist launcher.\n *\n * Main establishes the shared CArtAgO environment and creates the research\n * organisation. Mathematical reasoning remains in the ASTRA agents.\n */\nagent Main extends ResearchOntology {\n    module Cartago cartago;\n    module Console console;\n    module System S;\n\n    types bootstrap {\n        formula environment_ready();\n        formula artifact(string, cartago.ArtifactId);\n        formula worker_ready(string);\n        formula organisation_ready();\n    }\n\n    rule +!main(list args) {\n        !banner();\n        !environment_ready();\n        !artifacts_ready();\n        !agents_created();\n    }\n\n    rule +!banner() {\n        console.println("=== ASTRA Mathematician-Scientist ===");\n        console.println("BDI research + GL candidates + CArtAgO instruments + FIPA-ACL");\n        console.println("");\n    }\n\n    rule +!environment_ready() {\n        cartago.startService();\n        cartago.link();\n        +environment_ready();\n        console.println("[Main] CArtAgO environment ready.");\n    }\n\n    rule +!artifacts_ready() : environment_ready() {\n        !artifact_ready("knowledge", "artifacts.KnowledgeArtifact");\n        !artifact_ready("discoveries", "artifacts.DiscoveryArtifact");\n        !artifact_ready("math", "artifacts.MathArtifact");\n        !artifact_ready("number-theory", "artifacts.NumberTheoryArtifact");\n        !artifact_ready("counterexample", "artifacts.CounterexampleArtifact");\n        !artifact_ready("numerical", "artifacts.NumericalArtifact");\n        !artifact_ready("linear-algebra", "artifacts.LinearAlgebraArtifact");\n        !artifact_ready("formal-prover", "artifacts.FormalProverArtifact");\n        !artifact_ready("physics", "artifacts.PhysicsArtifact");\n    }\n\n    rule +!artifact_ready(string name, string className) {\n        try {\n            cartago.lookupArtifact(name, cartago.ArtifactId id);\n            +artifact(name, id);\n        } recover {\n            cartago.makeArtifact(name, className, cartago.params([]), cartago.ArtifactId id);\n            +artifact(name, id);\n        }\n        console.println("[Main] Artifact ready: " + name);\n    }\n\n    // REACTIVE: workers explicitly announce readiness. We do not rely on sleeps.\n    rule @message(inform, string sender, agent_ready(string role)) {\n        +worker_ready(role);\n        console.println("[Main] Ready: " + role + " (" + sender + ")");\n    }\n\n    // ACHIEVEMENT: create each worker and wait for its explicit readiness event.\n    rule +!agents_created() {\n        S.createAgent("knowledge", "KnowledgeAgent");\n        wait(worker_ready("knowledge"));\n\n        S.createAgent("counterexample", "CounterexampleAgent");\n        wait(worker_ready("counterexample"));\n\n        S.createAgent("reviewer", "ReviewerAgent");\n        wait(worker_ready("reviewer"));\n\n        S.createAgent("formal-verifier", "FormalVerifierAgent");\n        wait(worker_ready("formal-verifier"));\n\n        S.createAgent("proof-strategy", "ProofStrategyAgent");\n        wait(worker_ready("proof-strategy"));\n\n        S.createAgent("formalization", "FormalizationAgent");\n        wait(worker_ready("formalization"));\n\n        S.createAgent("conjecture", "ConjectureAgent");\n        wait(worker_ready("conjecture"));\n\n        S.createAgent("scientist", "ScientistAgent");\n        wait(worker_ready("scientist"));\n\n        S.createAgent("director", "ResearchDirector");\n        +organisation_ready();\n        console.println("[Main] Research organisation created.");\n    }\n\n    rule -!environment_ready() : ~environment_ready() {\n        console.println("[Main] CArtAgO environment initialisation FAILED.");\n    }\n\n    rule -!agents_created() : ~organisation_ready() {\n        console.println("[Main] Research organisation creation FAILED.");\n    }\n}\n',
  'astra/ProofStrategyAgent.astra': '// Pipeline: request > !strategy_generated > GL candidate > inform(scientist)\nagent ProofStrategyAgent extends ResearchOntology {\n    module gl.astra.GL gl;\n    module Console console;\n    module Cartago cartago;\n\n    types strategy_state {\n        formula binding(string);\n        formula strategy_generated(string);\n    }\n\n    initial !start();\n\n    rule +!start() {\n        cartago.link();\n        +binding(gl.bind("proof-strategy-agent", "groq", "openai/gpt-oss-120b", ""));\n        send(inform, "main", agent_ready("proof-strategy"));\n        console.println("[ProofStrategy] Ready.");\n    }\n\n    rule @message(request, string sender,\n                  proof_strategy_request(string taskId, string cid, string statement)) {\n        !strategy_generated(taskId, cid, statement, sender);\n    }\n\n    rule +!strategy_generated(string taskId, string cid,\n                              string statement, string sender) :\n        binding(string bid) {\n        !strategy_deliberated(taskId, cid,\n            gl.call(bid, taskId + "-strategy", "llm.answer", "ANSWER",\n                "Choose a rigorous proof strategy for this mathematical statement: " +\n                statement + ". Prefer direct proof, induction, contradiction, " +\n                "contrapositive, cases, modular arithmetic, invariants or descent as appropriate. " +\n                "Return one concrete method and a compact proof outline. " +\n                "Do not return UNKNOWN.",\n                "method,outline", ""),\n            sender);\n    }\n\n    rule +!strategy_deliberated(string taskId, string cid,\n                                string rid, string sender) :\n        gl.decide(gl.candidate(rid)) == "ADMISSIBLE" &\n        gl.get(gl.candidate(rid), "method") ~= "UNKNOWN" {\n        string scid = gl.candidate(rid);\n        gl.accept(scid, "proof strategy retained");\n        send(inform, sender,\n            proof_strategy_response(taskId, cid, scid,\n                gl.get(scid, "method"), gl.get(scid, "outline")));\n        +strategy_generated(taskId);\n    }\n\n    rule +!strategy_deliberated(string taskId, string cid,\n                                string rid, string sender) {\n        send(inform, sender,\n            proof_strategy_failed(taskId, cid,\n                "No admissible concrete proof strategy was generated."));\n    }\n\n    rule -!strategy_generated(string taskId, string cid,\n                              string statement, string sender) :\n        ~strategy_generated(taskId) {\n        send(inform, sender,\n            proof_strategy_failed(taskId, cid,\n                "proof strategy generation execution failed"));\n    }\n}\n',
  'astra/ResearchDirector.astra': '// Pipeline: start > !commissioned > send(request) > @message(result) > !reported\nagent ResearchDirector extends ResearchOntology {\n    module Console console;\n    module System S;\n\n    types director_state {\n        formula active_research(string, string);\n        formula research_complete(string);\n        formula reported(string);\n    }\n\n    // Default benchmark: intentionally asks the organisation to rediscover or\n    // reject a known divisibility theorem so the end-to-end protocol can be tested.\n    initial !start();\n\n    rule +!start() {\n        +active_research("research-001",\n            "Search for a non-trivial integer divisibility theorem involving n^3-n and construct a rigorous proof.");\n        !commissioned("research-001");\n    }\n\n    rule +!commissioned(string taskId) :\n        active_research(taskId, string problem) {\n        console.println("[Director] Commissioning research task " + taskId);\n        console.println("[Director] " + problem);\n        send(request, "scientist",\n             research_request(taskId, problem, "DISCOVERY"));\n    }\n\n    rule @message(inform, string sender,\n                  research_result(string taskId, string cid,\n                                  string status, string statement)) {\n        !reported_result(taskId, cid, status, statement);\n    }\n\n    // Reporting is deliberately distinct from promotion to established knowledge.\n    rule +!reported_result(string taskId, string cid,\n                           string status, string statement) :\n        ~reported(taskId) {\n        console.println("");\n        console.println("[Director] Research result");\n        console.println("[Director] task      = " + taskId);\n        console.println("[Director] candidate = " + cid);\n        console.println("[Director] status    = " + status);\n        console.println("[Director] statement = " + statement);\n\n        if (status == "FORMALLY_VERIFIED_NOVELTY_UNRESOLVED") {\n            console.println("[Director] Formal correctness passed, but novelty is unresolved.");\n            console.println("[Director] External literature search and human mathematical review are required.");\n        }\n\n        if (status == "FORMALLY_VERIFIED_KNOWN_LOCAL") {\n            console.println("[Director] The result is formally verified but matches the local known corpus.");\n        }\n\n        console.println("[Director] No result is promoted to established knowledge automatically.");\n        console.println("=== Research Complete ===");\n        +reported(taskId);\n        +research_complete(taskId);\n        S.exit();\n    }\n\n    rule +!reported_result(string taskId, string cid,\n                           string status, string statement) :\n        reported(taskId) {\n        console.println("[Director] Result already reported for " + taskId);\n    }\n\n    rule -!commissioned(string taskId) : ~research_complete(taskId) {\n        console.println("[Director] Failed to commission " + taskId);\n    }\n}\n',
  'astra/ResearchOntology.astra': '/**\n * Shared FIPA-ACL vocabulary for the mathematical research organisation.\n *\n * The ontology defines message content only. Decisions remain in the\n * individual agents\' beliefs, goals and plans.\n */\nagent ResearchOntology {\n\n    types research_ontology {\n        formula agent_ready(string);\n\n        formula research_request(string, string, string);\n            // taskId, problem, mode\n\n        formula research_result(string, string, string, string);\n            // taskId, candidateId, status, statement\n\n        formula conjecture_request(string, string, string);\n            // taskId, problem, context\n\n        formula conjecture_proposed(string, string, string, string, string, string, string, string, string);\n            // taskId, candidateId, statement, leanProposition,\n            // testPredicate, variable, min, max, symbolicCheck\n\n        formula conjecture_failed(string, string);\n            // taskId, reason\n\n        formula formalization_review_request(string, string, string, string);\n            // taskId, candidateId, naturalStatement, leanProposition\n\n        formula formalization_review_response(string, string, string, string, double);\n            // taskId, candidateId, verdict, reason, confidence\n\n        formula proof_strategy_request(string, string, string);\n            // taskId, candidateId, statement\n\n        formula proof_strategy_response(string, string, string, string, string);\n            // taskId, candidateId, strategyCandidateId, method, outline\n\n        formula proof_strategy_failed(string, string, string);\n            // taskId, candidateId, reason\n\n        formula counterexample_request(string, string, string, string, string, string);\n            // taskId, candidateId, predicate, variable, min, max\n\n        formula counterexample_response(string, string, string, string);\n            // taskId, candidateId, status, witness\n\n        formula proof_review_request(string, string, string, string, string, string, string, string);\n            // taskId, conjectureCandidateId, proofCandidateId, round,\n            // naturalStatement, leanProposition, symbolicCheck, proof\n\n        formula proof_review_response(string, string, string, string, string, double);\n            // taskId, proofCandidateId, round, verdict, reason, confidence\n\n        formula formal_verification_request(string, string, string, string);\n            // taskId, proofCandidateId, leanProposition, leanProof\n\n        formula formal_verification_response(string, string, string, string);\n            // taskId, proofCandidateId, status, details\n\n        formula novelty_request(string, string, string);\n            // taskId, proofCandidateId, statement\n\n        formula novelty_response(string, string, string, string);\n            // taskId, proofCandidateId, localCorpusStatus, evidence\n    }\n}\n',
  'astra/ReviewerAgent.astra': '// Pipeline: review request > deterministic evidence > GL critique > GL assessment > inform(scientist)\nagent ReviewerAgent extends ResearchOntology {\n    module gl.astra.GL gl;\n    module Console console;\n    module Cartago cartago;\n\n    types reviewer_state {\n        formula binding(string);\n        formula math_instrument(cartago.ArtifactId);\n        formula review_complete(string);\n    }\n\n    initial !start();\n\n    rule +!start() {\n        cartago.link();\n        cartago.lookupArtifact("math", cartago.ArtifactId mid);\n        +math_instrument(mid);\n        +binding(gl.bind("reviewer-agent", "groq", "openai/gpt-oss-120b", ""));\n        send(inform, "main", agent_ready("reviewer"));\n        console.println("[Reviewer] Ready.");\n    }\n\n    rule @message(request, string sender,\n                  proof_review_request(string taskId, string conjectureCid,\n                                       string proofCid, string round,\n                                       string statement, string leanProposition,\n                                       string symbolicCheck, string proof)) {\n        !reviewed(taskId, conjectureCid, proofCid, round,\n                  statement, leanProposition, symbolicCheck, proof, sender);\n    }\n\n    // The reviewer independently repeats any symbolic check before asking GL\n    // to critique the proof.\n    rule +!reviewed(string taskId, string conjectureCid, string proofCid,\n                    string round, string statement, string leanProposition,\n                    string symbolicCheck, string proof, string sender) :\n        symbolicCheck == "NONE" {\n        !generated_review(taskId, proofCid, round, statement, leanProposition,\n                          proof, "NO_SYMBOLIC_CHECK_SUPPLIED", sender);\n    }\n\n    rule +!reviewed(string taskId, string conjectureCid, string proofCid,\n                    string round, string statement, string leanProposition,\n                    string symbolicCheck, string proof, string sender) :\n        symbolicCheck ~= "NONE" &\n        math_instrument(cartago.ArtifactId mid) {\n        cartago.operation(mid,\n            simplify(symbolicCheck, string symbolicResult));\n        !generated_review(taskId, proofCid, round, statement, leanProposition,\n                          proof, symbolicResult, sender);\n    }\n\n    rule +!generated_review(string taskId, string proofCid, string round,\n                            string statement, string leanProposition,\n                            string proof, string symbolicEvidence, string sender) :\n        binding(string bid) {\n        !review_deliberated(taskId, proofCid, round,\n            gl.call(bid, taskId + "-review-" + round,\n                "reflect.critique", "REFLECTION",\n                "Act as an independent mathematical reviewer. " +\n                "Natural statement: " + statement + ". " +\n                "Previously reviewed Lean proposition: " + leanProposition + ". " +\n                "Candidate proof: " + proof + ". " +\n                "Independent symbolic evidence: " + symbolicEvidence + ". " +\n                "Check assumptions, quantifiers, domains, missing cases, circularity, " +\n                "unsupported algebra and whether the proof actually establishes the stated theorem. " +\n                "Return verdict exactly APPROVE, REVISE, or REJECT. " +\n                "REVISE means the core approach may be repairable; REJECT means a fundamental failure. " +\n                "Return a concrete reason.",\n                "verdict,reason", ""),\n            sender);\n    }\n\n    rule +!review_deliberated(string taskId, string proofCid, string round,\n                              string rid, string sender) :\n        gl.decide(gl.candidate(rid)) == "ADMISSIBLE" &\n        gl.get(gl.candidate(rid), "verdict") == "APPROVE" {\n        string rcid = gl.candidate(rid);\n        string reason = gl.get(rcid, "reason");\n        gl.accept(rcid, "review output retained");\n        string assessmentId =\n            gl.judge(proofCid, "reviewer-agent", "APPROVE", 0.90, reason);\n        +review_complete(proofCid);\n        send(inform, sender,\n            proof_review_response(taskId, proofCid, round,\n                                  "APPROVE", reason, 0.90));\n    }\n\n    rule +!review_deliberated(string taskId, string proofCid, string round,\n                              string rid, string sender) :\n        gl.decide(gl.candidate(rid)) == "ADMISSIBLE" &\n        gl.get(gl.candidate(rid), "verdict") == "REVISE" {\n        string rcid = gl.candidate(rid);\n        string reason = gl.get(rcid, "reason");\n        gl.accept(rcid, "review output retained");\n        string assessmentId =\n            gl.judge(proofCid, "reviewer-agent", "WARN", 0.80, reason);\n        +review_complete(proofCid);\n        send(inform, sender,\n            proof_review_response(taskId, proofCid, round,\n                                  "REVISE", reason, 0.80));\n    }\n\n    rule +!review_deliberated(string taskId, string proofCid, string round,\n                              string rid, string sender) :\n        gl.decide(gl.candidate(rid)) == "ADMISSIBLE" &\n        gl.get(gl.candidate(rid), "verdict") == "REJECT" {\n        string rcid = gl.candidate(rid);\n        string reason = gl.get(rcid, "reason");\n        gl.accept(rcid, "review output retained");\n        string assessmentId =\n            gl.judge(proofCid, "reviewer-agent", "REJECT_VERDICT", 0.90, reason);\n        +review_complete(proofCid);\n        send(inform, sender,\n            proof_review_response(taskId, proofCid, round,\n                                  "REJECT", reason, 0.90));\n    }\n\n    rule +!review_deliberated(string taskId, string proofCid, string round,\n                              string rid, string sender) {\n        send(inform, sender,\n            proof_review_response(taskId, proofCid, round,\n                                  "REVIEW_FAILED",\n                                  "No admissible structured review was produced.", 1.0));\n    }\n\n    rule -!reviewed(string taskId, string conjectureCid, string proofCid,\n                    string round, string statement, string leanProposition,\n                    string symbolicCheck, string proof, string sender) :\n        ~review_complete(proofCid) {\n        send(inform, sender,\n            proof_review_response(taskId, proofCid, round,\n                                  "REVIEW_FAILED",\n                                  "review execution failed", 1.0));\n    }\n}\n',
  'astra/ScientistAgent.astra': '// Pipeline:\n// research_request > conjecture > formalization + falsification + strategy\n// > proof > independent review > revision loop > exact Lean verification\n// > local-corpus check > report\nagent ScientistAgent extends ResearchOntology {\n    module gl.astra.GL gl;\n    module Cartago cartago;\n    module Console console;\n\n    types scientist_state {\n        formula binding(string);\n        formula discovery_store(cartago.ArtifactId);\n        formula math_instrument(cartago.ArtifactId);\n        formula requester(string, string);\n        formula research_problem(string, string);\n\n        formula conjecture_ready(string, string, string, string, string, string, string, string, string);\n        formula formalization_clear(string, string);\n        formula strategy_ready(string, string, string, string);\n        formula counterexample_clear(string, string);\n        formula proof_started(string, string);\n        formula proof_ready(string, string, string, string, string, string, string, string, string);\n        formula terminal(string);\n        formula ready_to_prove(string, string);\n    }\n\n    initial !start();\n\n    // DOMAIN MODEL: a proof attempt is justified only after three independent\n    // prerequisites hold in the scientist\'s belief base.\n    inference ready_to_prove(string taskId, string cid) :-\n        counterexample_clear(taskId, cid) &\n        formalization_clear(taskId, cid) &\n        strategy_ready(taskId, cid, string _, string _);\n\n    rule +!start() {\n        cartago.link();\n        cartago.lookupArtifact("discoveries", cartago.ArtifactId did);\n        cartago.lookupArtifact("math", cartago.ArtifactId mid);\n        +discovery_store(did);\n        +math_instrument(mid);\n        +binding(gl.bind("scientist-agent", "groq", "openai/gpt-oss-120b", ""));\n        send(inform, "main", agent_ready("scientist"));\n        console.println("[Scientist] Ready.");\n    }\n\n    // REACTIVE: a FIPA request becomes a BDI research goal.\n    rule @message(request, string sender,\n                  research_request(string taskId, string problem, string mode)) {\n        +requester(taskId, sender);\n        +research_problem(taskId, problem);\n        !investigated(taskId, problem);\n    }\n\n    // DECOMPOSITION: generated material is requested but not adopted.\n    rule +!investigated(string taskId, string problem) {\n        send(request, "conjecture",\n            conjecture_request(taskId, problem,\n                "Generate a precise falsifiable conjecture and a separate Lean proposition."));\n    }\n\n    rule @message(inform, string sender,\n                  conjecture_failed(string taskId, string reason)) :\n        ~terminal(taskId) {\n        +terminal(taskId);\n        !reported(taskId, "", "CONJECTURE_GENERATION_FAILED", reason);\n    }\n\n    // REACTIVE: keep generated content in the discovery/candidate layer.\n    rule @message(inform, string sender,\n                  conjecture_proposed(string taskId, string cid,\n                                      string statement, string leanProposition,\n                                      string predicate, string variable,\n                                      string min, string max,\n                                      string symbolicCheck)) :\n        discovery_store(cartago.ArtifactId did) &\n        ~terminal(taskId) {\n        +conjecture_ready(taskId, cid, statement, leanProposition,\n                          predicate, variable, min, max, symbolicCheck);\n        cartago.operation(did,\n            recordDiscovery(taskId, cid, "CONJECTURE", statement,\n                            "GENERATED", "GL"));\n        !symbolic_checked(cid, symbolicCheck);\n        !challenged(taskId, cid, statement, leanProposition,\n                    predicate, variable, min, max, symbolicCheck);\n    }\n\n    // ACHIEVEMENT: deterministic symbolic evidence is evidence, never proof.\n    rule +!symbolic_checked(string cid, string symbolicCheck) :\n        symbolicCheck == "NONE" &\n        discovery_store(cartago.ArtifactId did) {\n        cartago.operation(did,\n            addEvidence(cid, "SCIENTIST_SYMBOLIC", "NOT_SUPPLIED"));\n    }\n\n    rule +!symbolic_checked(string cid, string symbolicCheck) :\n        symbolicCheck ~= "NONE" &\n        math_instrument(cartago.ArtifactId mid) &\n        discovery_store(cartago.ArtifactId did) {\n        cartago.operation(mid,\n            simplify(symbolicCheck, string symbolicResult));\n        cartago.operation(did,\n            addEvidence(cid, "SCIENTIST_SYMBOLIC", symbolicResult));\n    }\n\n    // DECOMPOSITION: falsification, proof strategy and formalization review\n    // can proceed independently.\n    rule +!challenged(string taskId, string cid, string statement,\n                      string leanProposition, string predicate,\n                      string variable, string min, string max,\n                      string symbolicCheck) {\n        send(request, "counterexample",\n            counterexample_request(taskId, cid, predicate, variable, min, max));\n        send(request, "proof-strategy",\n            proof_strategy_request(taskId, cid, statement));\n        send(request, "formalization",\n            formalization_review_request(taskId, cid, statement, leanProposition));\n    }\n\n    // FORMALIZATION REVIEW\n    rule @message(inform, string sender,\n                  formalization_review_response(string taskId, string cid,\n                                                string verdict, string reason,\n                                                double confidence)) :\n        verdict == "APPROVE" &\n        ~terminal(taskId) &\n        discovery_store(cartago.ArtifactId did) {\n        +formalization_clear(taskId, cid);\n        cartago.operation(did,\n            addEvidence(cid, "FORMALIZATION_REVIEW", reason));\n        !prove_if_ready(taskId, cid);\n    }\n\n    rule @message(inform, string sender,\n                  formalization_review_response(string taskId, string cid,\n                                                string verdict, string reason,\n                                                double confidence)) :\n        verdict == "REJECT" &\n        conjecture_ready(taskId, cid, string statement, string _,\n                         string _, string _, string _, string _, string _) &\n        discovery_store(cartago.ArtifactId did) &\n        ~terminal(taskId) {\n        gl.reject(cid, "formalization rejected: " + reason);\n        cartago.operation(did,\n            updateStatus(cid, "FORMALIZATION_REJECTED", reason));\n        +terminal(taskId);\n        !reported(taskId, cid, "FORMALIZATION_REJECTED", statement);\n    }\n\n    rule @message(inform, string sender,\n                  formalization_review_response(string taskId, string cid,\n                                                string verdict, string reason,\n                                                double confidence)) :\n        verdict == "REVIEW_FAILED" &\n        conjecture_ready(taskId, cid, string statement, string _,\n                         string _, string _, string _, string _, string _) &\n        ~terminal(taskId) {\n        +terminal(taskId);\n        !reported(taskId, cid, "FORMALIZATION_REVIEW_FAILED", statement);\n    }\n\n    // PROOF STRATEGY\n    rule @message(inform, string sender,\n                  proof_strategy_response(string taskId, string cid,\n                                          string strategyCid,\n                                          string method, string outline)) :\n        ~terminal(taskId) {\n        +strategy_ready(taskId, cid, method, outline);\n        !prove_if_ready(taskId, cid);\n    }\n\n    rule @message(inform, string sender,\n                  proof_strategy_failed(string taskId, string cid,\n                                        string reason)) :\n        conjecture_ready(taskId, cid, string statement, string _,\n                         string _, string _, string _, string _, string _) &\n        ~terminal(taskId) {\n        +terminal(taskId);\n        !reported(taskId, cid, "PROOF_STRATEGY_FAILED", statement);\n    }\n\n    // COUNTEREXAMPLE SEARCH\n    rule @message(inform, string sender,\n                  counterexample_response(string taskId, string cid,\n                                          string status, string witness)) :\n        status == "FOUND" &\n        conjecture_ready(taskId, cid, string statement, string _,\n                         string _, string _, string _, string _, string _) &\n        discovery_store(cartago.ArtifactId did) &\n        ~terminal(taskId) {\n        cartago.operation(did,\n            updateStatus(cid, "DISPROVED", "counterexample=" + witness));\n        gl.reject(cid, "counterexample found: " + witness);\n        +terminal(taskId);\n        !reported(taskId, cid, "DISPROVED", statement);\n    }\n\n    rule @message(inform, string sender,\n                  counterexample_response(string taskId, string cid,\n                                          string status, string witness)) :\n        status == "NONE_FOUND" &\n        ~terminal(taskId) {\n        +counterexample_clear(taskId, cid);\n        !prove_if_ready(taskId, cid);\n    }\n\n    rule @message(inform, string sender,\n                  counterexample_response(string taskId, string cid,\n                                          string status, string witness)) :\n        status ~= "FOUND" &\n        status ~= "NONE_FOUND" &\n        conjecture_ready(taskId, cid, string statement, string _,\n                         string _, string _, string _, string _, string _) &\n        ~terminal(taskId) {\n        +terminal(taskId);\n        !reported(taskId, cid, "COUNTEREXAMPLE_SEARCH_" + status, statement);\n    }\n\n    // SERENDIPITY: prerequisites can arrive in any order, but only one initial\n    // proof attempt is adopted as an intention.\n    rule +!prove_if_ready(string taskId, string cid) :\n        ready_to_prove(taskId, cid) &\n        ~proof_started(taskId, cid) &\n        conjecture_ready(taskId, cid, string statement, string leanProposition,\n                         string _, string _, string _, string _, string symbolicCheck) &\n        strategy_ready(taskId, cid, string method, string outline) {\n        +proof_started(taskId, cid);\n        !proof_generated(taskId, cid, statement, leanProposition,\n                         symbolicCheck, method, outline, "1");\n    }\n\n    rule +!prove_if_ready(string taskId, string cid) {\n        // Not ready yet, or a proof attempt is already active.\n    }\n\n    // GL proposes a human proof plus ONLY the tactic body for the already\n    // reviewed Lean proposition.\n    rule +!proof_generated(string taskId, string conjectureCid,\n                           string statement, string leanProposition,\n                           string symbolicCheck, string method,\n                           string outline, string round) :\n        binding(string bid) {\n        !proof_deliberated(taskId, conjectureCid, statement, leanProposition,\n                           symbolicCheck, round,\n            gl.call(bid, taskId + "-proof-" + round,\n                "llm.answer", "ANSWER",\n                "Construct a rigorous mathematical proof of this exact statement: " +\n                statement + ". The fixed Lean proposition is: " + leanProposition + ". " +\n                "Chosen method: " + method + ". Strategy outline: " + outline + ". " +\n                "Return proof as a human-readable argument. " +\n                "Return leanProof as ONLY the Lean tactic body that belongs after \':= by\'. " +\n                "Do not include theorem, lemma, import, namespace, end, \':=\' or another proposition. " +\n                "Do not claim success if a required step is missing.",\n                "proof,leanProof", ""));\n    }\n\n    // ITERATIVE REFINEMENT: reviewer feedback is supplied to a new GL call.\n    rule +!proof_revised(string taskId, string conjectureCid,\n                         string statement, string leanProposition,\n                         string symbolicCheck, string previousProof,\n                         string reviewReason, string round) :\n        binding(string bid) {\n        !proof_deliberated(taskId, conjectureCid, statement, leanProposition,\n                           symbolicCheck, round,\n            gl.call(bid, taskId + "-proof-" + round,\n                "llm.answer", "ANSWER",\n                "Revise the mathematical proof in response to independent review. " +\n                "Exact statement: " + statement + ". " +\n                "Fixed Lean proposition: " + leanProposition + ". " +\n                "Previous proof: " + previousProof + ". " +\n                "Reviewer feedback: " + reviewReason + ". " +\n                "Return a corrected human-readable proof and leanProof containing ONLY " +\n                "the Lean tactic body after \':= by\'. Do not change the proposition.",\n                "proof,leanProof", ""));\n    }\n\n    rule +!proof_deliberated(string taskId, string conjectureCid,\n                             string statement, string leanProposition,\n                             string symbolicCheck, string round,\n                             string rid) :\n        gl.decide(gl.candidate(rid)) == "ADMISSIBLE" &\n        discovery_store(cartago.ArtifactId did) {\n        string proofCid = gl.candidate(rid);\n        string proof = gl.get(proofCid, "proof");\n        string leanProof = gl.get(proofCid, "leanProof");\n        +proof_ready(taskId, proofCid, conjectureCid, round,\n                     statement, leanProposition, symbolicCheck,\n                     proof, leanProof);\n        cartago.operation(did,\n            recordDiscovery(taskId, proofCid, "PROOF", statement,\n                            "PROOF_CANDIDATE", conjectureCid));\n        send(request, "reviewer",\n            proof_review_request(taskId, conjectureCid, proofCid, round,\n                                 statement, leanProposition,\n                                 symbolicCheck, proof));\n    }\n\n    rule +!proof_deliberated(string taskId, string conjectureCid,\n                             string statement, string leanProposition,\n                             string symbolicCheck, string round,\n                             string rid) :\n        ~terminal(taskId) {\n        +terminal(taskId);\n        !reported(taskId, conjectureCid, "PROOF_GENERATION_FAILED", statement);\n    }\n\n    // REVIEW: approval goes to Lean, revision creates a fresh GL candidate,\n    // rejection terminates this research branch.\n    rule @message(inform, string sender,\n                  proof_review_response(string taskId, string proofCid,\n                                        string round, string verdict,\n                                        string reason, double confidence)) :\n        verdict == "APPROVE" &\n        proof_ready(taskId, proofCid, string conjectureCid, round,\n                    string statement, string leanProposition,\n                    string symbolicCheck, string proof, string leanProof) &\n        discovery_store(cartago.ArtifactId did) &\n        ~terminal(taskId) {\n        cartago.operation(did,\n            updateStatus(proofCid, "AUTOMATED_REVIEW_APPROVED", reason));\n        send(request, "formal-verifier",\n            formal_verification_request(taskId, proofCid,\n                                        leanProposition, leanProof));\n    }\n\n    rule @message(inform, string sender,\n                  proof_review_response(string taskId, string proofCid,\n                                        string round, string verdict,\n                                        string reason, double confidence)) :\n        verdict == "REVISE" &\n        round == "1" &\n        proof_ready(taskId, proofCid, string conjectureCid, round,\n                    string statement, string leanProposition,\n                    string symbolicCheck, string proof, string leanProof) &\n        discovery_store(cartago.ArtifactId did) &\n        ~terminal(taskId) {\n        gl.reject(proofCid, "superseded after automated review: " + reason);\n        cartago.operation(did,\n            updateStatus(proofCid, "SUPERSEDED_REVISION", reason));\n        !proof_revised(taskId, conjectureCid, statement, leanProposition,\n                       symbolicCheck, proof, reason, "2");\n    }\n\n    rule @message(inform, string sender,\n                  proof_review_response(string taskId, string proofCid,\n                                        string round, string verdict,\n                                        string reason, double confidence)) :\n        verdict == "REVISE" &\n        round == "2" &\n        proof_ready(taskId, proofCid, string conjectureCid, round,\n                    string statement, string leanProposition,\n                    string symbolicCheck, string proof, string leanProof) &\n        discovery_store(cartago.ArtifactId did) &\n        ~terminal(taskId) {\n        gl.reject(proofCid, "superseded after automated review: " + reason);\n        cartago.operation(did,\n            updateStatus(proofCid, "SUPERSEDED_REVISION", reason));\n        !proof_revised(taskId, conjectureCid, statement, leanProposition,\n                       symbolicCheck, proof, reason, "3");\n    }\n\n    rule @message(inform, string sender,\n                  proof_review_response(string taskId, string proofCid,\n                                        string round, string verdict,\n                                        string reason, double confidence)) :\n        verdict == "REVISE" &\n        round == "3" &\n        proof_ready(taskId, proofCid, string conjectureCid, round,\n                    string statement, string _, string _, string _, string _) &\n        discovery_store(cartago.ArtifactId did) &\n        ~terminal(taskId) {\n        gl.reject(proofCid, "revision limit reached: " + reason);\n        cartago.operation(did,\n            updateStatus(proofCid, "REVISION_LIMIT_REACHED", reason));\n        +terminal(taskId);\n        !reported(taskId, proofCid, "REVISION_LIMIT_REACHED", statement);\n    }\n\n    rule @message(inform, string sender,\n                  proof_review_response(string taskId, string proofCid,\n                                        string round, string verdict,\n                                        string reason, double confidence)) :\n        verdict == "REJECT" &\n        proof_ready(taskId, proofCid, string conjectureCid, round,\n                    string statement, string _, string _, string _, string _) &\n        discovery_store(cartago.ArtifactId did) &\n        ~terminal(taskId) {\n        gl.reject(proofCid, "automated reviewer rejected proof: " + reason);\n        cartago.operation(did,\n            updateStatus(proofCid, "AUTOMATED_REVIEW_REJECTED", reason));\n        +terminal(taskId);\n        !reported(taskId, proofCid, "AUTOMATED_REVIEW_REJECTED", statement);\n    }\n\n    rule @message(inform, string sender,\n                  proof_review_response(string taskId, string proofCid,\n                                        string round, string verdict,\n                                        string reason, double confidence)) :\n        verdict == "REVIEW_FAILED" &\n        proof_ready(taskId, proofCid, string conjectureCid, round,\n                    string statement, string _, string _, string _, string _) &\n        ~terminal(taskId) {\n        +terminal(taskId);\n        !reported(taskId, proofCid, "AUTOMATED_REVIEW_FAILED", statement);\n    }\n\n    // FORMAL VERIFICATION: success applies only to the exact reviewed Lean\n    // proposition because the artifact constructs the theorem wrapper itself.\n    rule @message(inform, string sender,\n                  formal_verification_response(string taskId, string proofCid,\n                                               string status, string details)) :\n        status == "VERIFIED" &\n        proof_ready(taskId, proofCid, string conjectureCid, string round,\n                    string statement, string leanProposition,\n                    string symbolicCheck, string proof, string leanProof) &\n        discovery_store(cartago.ArtifactId did) &\n        ~terminal(taskId) {\n        gl.accept(proofCid, "Lean verified the fixed proposition");\n        gl.accept(conjectureCid, "Lean verified the fixed proposition through an accepted proof");\n        cartago.operation(did,\n            updateStatus(proofCid, "FORMALLY_VERIFIED", details));\n        cartago.operation(did,\n            updateStatus(conjectureCid, "FORMALLY_VERIFIED_THEOREM", details));\n        send(request, "knowledge",\n            novelty_request(taskId, proofCid, statement));\n    }\n\n    rule @message(inform, string sender,\n                  formal_verification_response(string taskId, string proofCid,\n                                               string status, string details)) :\n        status ~= "VERIFIED" &\n        proof_ready(taskId, proofCid, string conjectureCid, string round,\n                    string statement, string _, string _, string _, string _) &\n        discovery_store(cartago.ArtifactId did) &\n        ~terminal(taskId) {\n        gl.reject(proofCid, "formal verification failed: " + status);\n        cartago.operation(did,\n            updateStatus(proofCid, status, details));\n        +terminal(taskId);\n        !reported(taskId, proofCid, status, statement);\n    }\n\n    // LOCAL CORPUS CHECK: this never establishes global novelty.\n    rule @message(inform, string sender,\n                  novelty_response(string taskId, string proofCid,\n                                   string status, string evidence)) :\n        status == "KNOWN_LOCAL_EXACT" &\n        proof_ready(taskId, proofCid, string conjectureCid, string round,\n                    string statement, string _, string _, string _, string _) &\n        discovery_store(cartago.ArtifactId did) &\n        ~terminal(taskId) {\n        cartago.operation(did,\n            updateStatus(proofCid, "FORMALLY_VERIFIED_KNOWN_LOCAL", evidence));\n        +terminal(taskId);\n        !reported(taskId, proofCid, "FORMALLY_VERIFIED_KNOWN_LOCAL", statement);\n    }\n\n    rule @message(inform, string sender,\n                  novelty_response(string taskId, string proofCid,\n                                   string status, string evidence)) :\n        status == "NOT_FOUND_IN_LOCAL_CORPUS" &\n        proof_ready(taskId, proofCid, string conjectureCid, string round,\n                    string statement, string _, string _, string _, string _) &\n        discovery_store(cartago.ArtifactId did) &\n        ~terminal(taskId) {\n        cartago.operation(did,\n            updateStatus(proofCid,\n                "FORMALLY_VERIFIED_NOVELTY_UNRESOLVED",\n                evidence + "; external literature search and human mathematical review required"));\n        +terminal(taskId);\n        !reported(taskId, proofCid,\n            "FORMALLY_VERIFIED_NOVELTY_UNRESOLVED", statement);\n    }\n\n    rule @message(inform, string sender,\n                  novelty_response(string taskId, string proofCid,\n                                   string status, string evidence)) :\n        status ~= "KNOWN_LOCAL_EXACT" &\n        status ~= "NOT_FOUND_IN_LOCAL_CORPUS" &\n        proof_ready(taskId, proofCid, string conjectureCid, string round,\n                    string statement, string _, string _, string _, string _) &\n        ~terminal(taskId) {\n        +terminal(taskId);\n        !reported(taskId, proofCid,\n            "FORMALLY_VERIFIED_LOCAL_CORPUS_CHECK_FAILED", statement);\n    }\n\n    // Reporting is not promotion to established knowledge.\n    rule +!reported(string taskId, string cid, string status, string statement) :\n        requester(taskId, string receiver) {\n        send(inform, receiver,\n            research_result(taskId, cid, status, statement));\n    }\n\n    rule -!investigated(string taskId, string problem) : ~terminal(taskId) {\n        +terminal(taskId);\n        !reported(taskId, "", "RESEARCH_FAILED", problem);\n    }\n}\n'
});
